from author import add, save, write
write('shared/npm.mjs', '''
import {existsSync} from 'node:fs';import {dirname,join} from 'node:path';import {spawnNode} from './lab.mjs';
export function npm(args,options={}) {
 const candidates=[process.env.npm_execpath,join(dirname(process.execPath),'node_modules/npm/bin/npm-cli.js'),'/usr/share/nodejs/npm/bin/npm-cli.js','/usr/local/lib/node_modules/npm/bin/npm-cli.js'].filter(Boolean);
 const cli=candidates.find(existsSync);if(!cli)throw Error('Run this lesson with npm run lesson -- NUMBER so npm_execpath is available.');
 return spawnNode([cli,...args],options);
}
''')
add(22,'''import {promisify} from 'node:util';import assert from 'node:assert/strict';
function twice(n,cb){queueMicrotask(()=>{if(n<0)return cb(Error('negative'));cb(null,n*2);});}const run=promisify(twice);console.log(await run(3));await assert.rejects(run(-1),/negative/);console.log('negative rejected');''','The callback adapter yields 6, and an error-first rejection is handled.')
add(23,'''import assert from 'node:assert/strict';const work=()=>[Promise.resolve('A'),Promise.reject(Error('B failed')),Promise.resolve('C')];try{await Promise.all(work());}catch(e){console.log('all:',e.message);}console.log((await Promise.allSettled(work())).map(x=>x.status));console.log(await Promise.any(work()));await assert.rejects(Promise.any([Promise.reject(Error('x'))]),AggregateError);''','all rejects, allSettled retains three outcomes, any returns A, and all-rejected any raises AggregateError.')
add(24,'''import {assert,delay} from '../../shared/lab.mjs';async function a(){await delay(40);return 2;}async function b(){await delay(40);return 3;}let start=performance.now();const x=await a(),y=await b();console.log('sequential measured ms',performance.now()-start,x+y);start=performance.now();const values=await Promise.all([a(),b()]);console.log('concurrent measured ms',performance.now()-start,values[0]+values[1]);assert.equal(values[0]+values[1],5);''','Both workflows produce 5; independent waits overlap in the concurrent version. Timings are measured.')
add(25,'''import {assert,delay} from '../../shared/lab.mjs';
async function run(tasks,limit){if(!Number.isInteger(limit)||limit<1)throw Error('limit');let next=0;const results=[];await Promise.all(Array.from({length:Math.min(limit,tasks.length)},async()=>{while(next<tasks.length){const i=next++;try{results[i]={status:'fulfilled',value:await tasks[i]()};}catch(reason){results[i]={status:'rejected',reason:reason.message};}}}));return results;}
let active=0,max=0;const tasks=Array.from({length:20},(_,i)=>async()=>{active++;max=Math.max(max,active);try{await delay(5);if(i===5)throw Error('fixture failure');return i;}finally{active--;}});const rows=await run(tasks,3);console.log({max,rows});assert.ok(max<=3);assert.equal(rows[5].status,'rejected');await assert.rejects(run(tasks,0));''','Twenty tasks preserve result order with at most three active; one failure does not stop the remaining work.')
add(26,'''import {assert,delay} from '../../shared/lab.mjs';const caller=new AbortController();const combined=AbortSignal.any([caller.signal,AbortSignal.timeout(30)]);try{await delay(500,null,{signal:combined});assert.fail();}catch(e){console.log({thrown:e.name,reason:combined.reason.name});assert.equal(e.name,'AbortError');assert.equal(combined.reason.name,'TimeoutError');}''','The timers promise rejects AbortError; the combined signal records TimeoutError as its deadline reason.')
add(27,'''import assert from 'node:assert/strict';async function read(){throw Error('disk unavailable');}async function service(){try{return await read();}catch(cause){throw Error('Load failed',{cause});}finally{console.log('cleanup');}}try{await service();assert.fail();}catch(e){console.log(e.message,e.cause.message);assert.equal(e.cause.message,'disk unavailable');}''','Cleanup runs before the caller observes the wrapped error and its original cause.')
add(28,'''import assert from 'node:assert/strict';let requested=0,cleaned=false;async function* pages(){try{for(let p=1;p<=5;p++){requested++;yield [p*10];}}finally{cleaned=true;console.log('cleanup');}}for await(const page of pages()){console.log(page);break;}console.log({requested,cleaned});assert.equal(requested,1);assert.equal(cleaned,true);''','Only the first page is requested; breaking async iteration runs cleanup.')
add(29,'''import {add} from './math.js';import assert from 'node:assert/strict';console.log(add(2,3));assert.equal(add(2,3),5);await assert.rejects(import('./math'),{code:'ERR_MODULE_NOT_FOUND'});console.log('extensionless import rejected');''','ESM imports with explicit extensions work; Node rejects the extensionless fixture.',files={'math.js':"export const add=(a,b)=>a+b;"})
add(30,'''import {createRequire} from 'node:module';import assert from 'node:assert/strict';const require=createRequire(import.meta.url);const a=require('./state.cjs'),b=require('./state.cjs');console.log(a===b,a.next(),b.next());assert.equal(a,b);''','Resolved CommonJS module instances are cached; the two calls share the same counter.',files={'state.cjs':"let count=0;module.exports={next:()=>++count};"})
add(31,'''import {createRequire} from 'node:module';import assert from 'node:assert/strict';const require=createRequire(import.meta.url);console.log(require('./helper.cjs').answer);const esm=await import('./helper.mjs');console.log(esm.answer);assert.throws(()=>require('./helper.mjs'),{code:'ERR_REQUIRE_ASYNC_MODULE'});console.log('async ESM requires dynamic import');''','Both interop paths return 42; require rejects an ESM graph containing top-level await.',files={'helper.cjs':"module.exports={answer:42};",'helper.mjs':"export const answer=await Promise.resolve(42);"})
add(32,'''import {assert,fs,temp,join,spawnNode} from '../../shared/lab.mjs';import {npm} from '../../shared/npm.mjs';
await using lab=await temp();const lib=join(lab.path,'lib'),consumer=join(lab.path,'consumer');await fs.mkdir(lib);await fs.mkdir(consumer);await fs.mkdir(join(lib,'src'));
await fs.writeFile(join(lib,'package.json'),JSON.stringify({name:'course-demo-lib',version:'1.0.0',type:'module',exports:{'.':'./src/index.js'},imports:{'#utils':'./src/utils.js'}}));await fs.writeFile(join(lib,'src/utils.js'),'export const answer=42;');await fs.writeFile(join(lib,'src/index.js'),"export {answer} from '#utils';");
let r=await npm(['pack','--json','--ignore-scripts'],{cwd:lib});assert.equal(r.code,0,r.stderr);const tar=join(lib,JSON.parse(r.stdout)[0].filename);await fs.writeFile(join(consumer,'package.json'),'{"private":true,"type":"module"}');r=await npm(['install','--offline','--ignore-scripts','--no-audit','--no-fund',tar],{cwd:consumer});assert.equal(r.code,0,r.stderr);
await fs.writeFile(join(consumer,'test.mjs'),"import {answer} from 'course-demo-lib';console.log(answer);try{await import('course-demo-lib/src/utils.js');throw Error('must reject');}catch(e){if(e.code!=='ERR_PACKAGE_PATH_NOT_EXPORTED')throw e;console.log(e.code);}");r=await spawnNode(['test.mjs'],{cwd:consumer});console.log(r.stdout);assert.equal(r.code,0,r.stderr);''','A real tarball installs into a separate consumer: public import returns 42 and private subpath import fails.')
add(33,'''import assert from 'node:assert/strict';const plugins=new Map([['hello',()=>import('./plugins/hello.mjs')]]);async function load(name){const factory=plugins.get(name);if(!factory)throw Error('Unknown plugin');return(await factory()).run();}console.log(await load('hello'));await assert.rejects(load('../../secret'),/Unknown/);console.log('unknown path rejected before import');''','The allowlisted plugin runs; arbitrary path input is rejected.',files={'plugins/hello.mjs':"export const run=()=> 'hello';"})
add(34,'''import {readFile} from 'node:fs/promises';import settings from './settings.json' with {type:'json'};console.log(settings.title,(await readFile(new URL('./message.txt',import.meta.url),'utf8')).trim());''','Module-relative assets load consistently even when the shell current directory changes.',files={'settings.json':'{"title":"Demo"}','message.txt':'Hello'})
add(35,'''import {assert,spawnNode} from '../../shared/lab.mjs';const broken=await spawnNode(['a.mjs']);assert.notEqual(broken.code,0);console.log('cycle rejected:',broken.stderr.split('\\n').find(x=>x.includes('ReferenceError')));const fixed=await import('./fixed-a.mjs');console.log('acyclic:',fixed.value);assert.equal(fixed.value,2);''','An eagerly evaluated cycle fails; extracting shared state removes the cycle.',files={'a.mjs':"import {b} from './b.mjs';export const a=b+1;",'b.mjs':"import {a} from './a.mjs';export const b=a+1;",'shared.mjs':'export const base=1;','fixed-a.mjs':"import {base} from './shared.mjs';export const value=base+1;"})
add(36,'''import assert from 'node:assert/strict';import {readFile} from 'node:fs/promises';const manifest=JSON.parse(await readFile(new URL('./fixture-package.json',import.meta.url)));for(const kind of ['dependencies','devDependencies','peerDependencies','optionalDependencies'])console.log(kind,manifest[kind]);try{await import('course-not-installed-optional-fixture');}catch(e){assert.equal(e.code,'ERR_MODULE_NOT_FOUND');console.log('optional feature unavailable; baseline app continues');}console.log('engines declares compatibility, not runtime installation:',manifest.engines);''','The manifest separates dependency responsibilities and the optional feature has an actual fallback.',files={'fixture-package.json':'{"engines":{"node":"26.13.1"},"dependencies":{"runtime-lib":"file:./runtime-lib"},"devDependencies":{"test-lib":"file:./test-lib"},"peerDependencies":{"host-lib":"^1.0.0"},"optionalDependencies":{"optional-lib":"file:./optional-lib"}}'})
add(37,'''import {assert,fs,temp,join,spawnNode} from '../../shared/lab.mjs';await using lab=await temp();await fs.mkdir(join(lab.path,'dist'));await fs.writeFile(join(lab.path,'dist/generated.txt'),'generated');const r=await spawnNode(['--check','main.mjs']);assert.equal(r.code,0);await fs.rm(join(lab.path,'dist'),{recursive:true,force:true});await assert.rejects(fs.access(join(lab.path,'dist')));console.log('syntax checked; only owned generated dist removed');''','A portable Node cleanup removes only a generated, project-owned directory.',files={'main.mjs':"console.log('portable script');",'clean.mjs':"import {rm} from 'node:fs/promises';await rm(new URL('./dist/',import.meta.url),{recursive:true,force:true});"})
add(38,'''import {assert,fs,temp,join} from '../../shared/lab.mjs';import {npm} from '../../shared/npm.mjs';await using lab=await temp();await fs.mkdir(join(lab.path,'lib'));await fs.writeFile(join(lab.path,'lib/package.json'),'{"name":"course-local-lib","version":"1.0.0"}');const manifest={name:'course-lock-lab',version:'1.0.0',private:true,dependencies:{'course-local-lib':'file:./lib'}};await fs.writeFile(join(lab.path,'package.json'),JSON.stringify(manifest));for(const command of ['install','ci']){const r=await npm([command,'--offline','--ignore-scripts','--no-audit','--no-fund'],{cwd:lab.path});assert.equal(r.code,0,r.stderr);console.log(command,'succeeded');}manifest.dependencies.extra='file:./lib';await fs.writeFile(join(lab.path,'package.json'),JSON.stringify(manifest));const mismatch=await npm(['ci','--offline','--ignore-scripts','--no-audit','--no-fund'],{cwd:lab.path});assert.notEqual(mismatch.code,0);console.log('manifest/lock mismatch rejected');''','Offline local dependency installation creates a real lockfile; ci succeeds, then rejects manifest drift.')
add(39,'''import semver from 'semver';import assert from 'node:assert/strict';for(const [range,yes,no] of [['1.2.3','1.2.3','1.2.4'],['^1.2.3','1.9.0','2.0.0'],['~1.2.3','1.2.9','1.3.0'],['^0.2.3','0.2.9','0.3.0']]){console.log(range,yes,semver.satisfies(yes,range),no,semver.satisfies(no,range));assert.ok(semver.satisfies(yes,range));assert.ok(!semver.satisfies(no,range));}''','Real semver evaluation demonstrates exact, caret, tilde, and pre-1.0 ranges.',deps=['semver'])
add(40,'''import {assert,fs,temp,join,spawnNode} from '../../shared/lab.mjs';import {npm} from '../../shared/npm.mjs';await using lab=await temp();for(const name of ['math','cli'])await fs.mkdir(join(lab.path,'packages',name),{recursive:true});await fs.writeFile(join(lab.path,'package.json'),JSON.stringify({private:true,workspaces:['packages/*']}));await fs.writeFile(join(lab.path,'packages/math/package.json'),JSON.stringify({name:'@demo/math',version:'1.0.0',type:'module',exports:'./index.js'}));await fs.writeFile(join(lab.path,'packages/math/index.js'),'export const add=(a,b)=>a+b;');await fs.writeFile(join(lab.path,'packages/cli/package.json'),JSON.stringify({name:'@demo/cli',version:'1.0.0',type:'module',dependencies:{'@demo/math':'1.0.0'}}));await fs.writeFile(join(lab.path,'packages/cli/main.mjs'),"import {add} from '@demo/math';console.log(add(2,3));");const installed=await npm(['install','--offline','--ignore-scripts','--no-audit','--no-fund'],{cwd:lab.path});assert.equal(installed.code,0,installed.stderr);const r=await spawnNode(['packages/cli/main.mjs'],{cwd:lab.path});console.log(r.stdout);assert.equal(r.stdout.trim(),'5');''','Two real local workspaces link without workspace:* syntax; the CLI imports the math package.')
add(41,'''import {npm} from '../../shared/npm.mjs';import {fileURLToPath} from 'node:url';const root=fileURLToPath(new URL('../../',import.meta.url));const args=process.argv.includes('--audit')?['audit','--json']:['ls','--depth=0'];const r=await npm(args,{cwd:root});console.log(r.stdout);if(r.stderr)console.error(r.stderr);if(args[0]==='ls'&&r.code!==0)process.exitCode=r.code;console.log(args[0]==='audit'?'Review live advisory reachability; no automatic fixes were applied.':'Use --audit to request a live registry advisory report.');''','The actual installed graph is inspected. --audit optionally requests live advisories; no fabricated vulnerability counts or force-fixes.',deps=['npm CLI'])
add(42,'''import {assert,fs,temp,join} from '../../shared/lab.mjs';import {npm} from '../../shared/npm.mjs';await using lab=await temp();await fs.mkdir(join(lab.path,'dist'));await fs.writeFile(join(lab.path,'package.json'),JSON.stringify({name:'course-package-fixture',version:'1.0.0',type:'module',files:['dist'],exports:'./dist/index.js'}));await fs.writeFile(join(lab.path,'dist/index.js'),'export const answer=42;');await fs.writeFile(join(lab.path,'secret-fixture.txt'),'PUBLIC TEST FIXTURE - MUST BE EXCLUDED');const r=await npm(['pack','--dry-run','--json','--ignore-scripts'],{cwd:lab.path});assert.equal(r.code,0,r.stderr);const files=JSON.parse(r.stdout)[0].files.map(x=>x.path);console.log(files);assert.ok(files.includes('dist/index.js'));assert.ok(!files.includes('secret-fixture.txt'));console.log('allowlist verified; nothing published');''','The npm pack dry run includes the distributable entry and excludes the secret-shaped fixture. No package is published.')
